namespace cmdline {

    void LTH(int img_size) {

        // ADD YOUR CODE HERE
        graphic::Screen screen;
        unsigned char header_data[54];

        const unsigned char* img;

        if (img_size == 50) {
            img = lth_50_50;
        } else if (img_size == 100) {
            img = lth_100_100;
        } else {
            throw std::invalid_argument("Unknown image_size " + std::to_string(img_size));
        }

        std::memcpy(header_data, img, 54);

        int offset_to_pixel = *((int*) &header_data[10]);
        int width = *((int*) &header_data[18]);
        int height = *((int*) &header_data[22]);

        const int padding = (4 - (3 * width) % 4) % 4;

        screen.resize(width, height);

        const unsigned char* pixel_data = img + offset_to_pixel;

        const unsigned char* p = pixel_data;
        for (int j = height - 1; j >= 0; --j) {
            for (int i = 0; i < width; ++i) {
                unsigned char b = *p++;
                unsigned char g = *p++;
                unsigned char r = *p++;
                screen.pixel(i, j).set((int) r, (int) g, (int) b);
            }
            p += padding;
        }

        std::cout << screen;

    }

}

